<script setup lang="ts">
import {computed,ref,watch} from 'vue';import {useRoute} from 'vue-router';import PageHeader from '@/components/shared/PageHeader.vue';import BaseBadge from '@/components/base/BaseBadge.vue';import {ModuleService,ReportService} from '@/services';import ModuleFields from '@/components/shared/ModuleFields.vue';import {moduleStatuses} from '@/services/modules';import {sameDay,formatDate,parseDate} from '@/utils/dates';import type {ModuleRecord} from '@/mocks/modules';import {useAppStore} from '@/stores/app';import {Search,Plus,Download,X,MoreHorizontal,Trash2,Eye} from 'lucide-vue-next';
const route=useRoute(),app=useAppStore(),kind=computed(()=>String(route.meta.kind));const configs:any={employees:['Funcionários','Pessoas, setores e vínculos com os recursos de TI','Funcionário'],maintenance:['Manutenções','Planejamento de manutenções corretivas e preventivas','Manutenção'],inventory:['Estoque','Peças, periféricos e movimentações do almoxarifado de TI','Item'],loans:['Empréstimos','Controle de retirada, condição e devolução de equipamentos','Empréstimo'],suppliers:['Fornecedores','Fornecedores, contratos e contatos comerciais','Fornecedor'],infrastructure:['Infraestrutura','Serviços, rede, servidores e disponibilidade operacional','Recurso'],knowledge:['Base de Conhecimento','Procedimentos e soluções compartilhados pela equipe','Artigo']};const c=computed(()=>configs[kind.value]);const items=ref<ModuleRecord[]>([]),query=ref(''),modal=ref(false),menu=ref<number|null>(null);const form=ref<ModuleRecord>({id:0,name:'',category:'',info:'',status:'Ativo',owner:'',email:'',phone:'',notes:'',updatedAt:'Agora'});watch(()=>[kind.value,route.query.q],()=>{items.value=ModuleService.list(kind.value);query.value=String(route.query.q||'');modal.value=false;menu.value=null},{immediate:true});const filtered=computed(()=>items.value.filter(x=>`${x.name} ${x.category} ${x.info}`.toLowerCase().includes(query.value.toLowerCase())&&(!route.query.status||x.status===route.query.status)&&(route.query.overdue!=='1'||(!['Concluída','Cancelada'].includes(x.status)&&(x.status==='Atrasada'||(parseDate(x.scheduledAt)?.getTime()??Infinity)<Date.now())))));const metrics=computed(()=>[['Registros',items.value.length],['Ativos / operacionais',items.value.filter(x=>['Ativo','Operacional','Publicado','Normal','Em andamento'].includes(x.status)).length],['Requerem atenção',items.value.filter(x=>['Atrasado','Atrasada','Indisponível','Estoque baixo'].includes(x.status)).length],['Atualizados hoje',items.value.filter(x=>sameDay(x.updatedAt)).length]]);
function openNew(){form.value={id:0,name:'',category:'',info:'',status:moduleStatuses[kind.value]?.[0]||'Ativo',owner:'',email:'',phone:'',notes:'',updatedAt:new Date().toISOString()};modal.value=true}function save(){try{const item={...form.value,name:form.value.name.trim(),category:form.value.category.trim(),id:Math.max(0,...items.value.map(x=>x.id))+1,updatedAt:new Date().toISOString()};ModuleService.save(kind.value,[item,...items.value]);items.value=ModuleService.list(kind.value);modal.value=false;app.toast('Cadastro salvo','O registro foi salvo localmente.')}catch(error){app.toast('Falha ao salvar',error instanceof Error?error.message:String(error),'error')}}function remove(id:number){if(confirm('Excluir este registro?')){items.value=items.value.filter(x=>x.id!==id);ModuleService.save(kind.value,items.value);menu.value=null;app.toast('Registro excluído','A alteração foi salva localmente.','warning')}}function exportPdf(){ReportService.exportPdf(c.value[0],['Nome','Categoria','Informação','Status'],filtered.value.map(x=>[x.name,x.category,x.info,x.status]));app.toast('Relatório gerado',`O PDF de ${c.value[0].toLowerCase()} foi baixado.`)}
</script>
<template><PageHeader :title="c[0]" :description="c[1]"><button class="btn btn-secondary" @click="exportPdf"><Download class="size-4"/>Exportar PDF</button><button class="btn btn-primary" @click="openNew"><Plus class="size-4"/>Novo {{c[2]}}</button></PageHeader><div class="grid grid-cols-4 gap-3"><div v-for="m in metrics" :key="String(m[0])" class="card p-3"><div class="text-xs text-slate-500">{{m[0]}}</div><b class="mt-1 block text-xl">{{m[1]}}</b></div></div><div class="card mt-3 overflow-visible"><div class="flex border-b p-3 dark:border-slate-700"><div class="relative w-80"><Search class="absolute left-3 top-2.5 size-4 text-slate-400"/><input v-model="query" class="field pl-9" placeholder="Nome ou código"/></div></div><table class="w-full text-left text-xs"><thead class="table-head"><tr><th class="px-4 py-3">Nome / Recurso</th><th>Categoria</th><th>Informação</th><th>Responsável / Local</th><th>Status</th><th>Atualização</th><th></th></tr></thead><tbody><tr v-for="r in filtered" :key="r.id" class="border-t border-slate-100 hover:bg-slate-50 dark:border-slate-700 dark:hover:bg-slate-700/30"><td class="px-4 py-4"><router-link :to="`${route.path}/${r.id}`" class="font-semibold text-blue-600">{{r.name}}</router-link></td><td>{{r.category}}</td><td>{{r.info}}</td><td>{{r.owner}}</td><td><BaseBadge :label="r.status"/></td><td>{{formatDate(r.updatedAt)}}</td><td class="relative"><button @click="menu=menu===r.id?null:r.id"><MoreHorizontal class="size-4"/></button><div v-if="menu===r.id" class="card absolute right-4 top-8 z-20 w-36 p-1 shadow-lg"><router-link :to="`${route.path}/${r.id}`" class="flex gap-2 rounded px-3 py-2 hover:bg-slate-50 dark:hover:bg-slate-700"><Eye class="size-3"/>Abrir</router-link><button class="flex w-full gap-2 rounded px-3 py-2 text-red-600 hover:bg-red-50" @click="remove(r.id)"><Trash2 class="size-3"/>Excluir</button></div></td></tr></tbody></table><div v-if="!filtered.length" class="p-12 text-center text-sm text-slate-400">Nenhum registro encontrado.</div></div><div v-if="modal" class="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/45" @mousedown.self="modal=false"><form class="card max-h-[90vh] w-[720px] overflow-y-auto shadow-2xl" @submit.prevent="save"><div class="flex items-center justify-between border-b px-6 py-4 dark:border-slate-700"><div><h2 class="font-bold">Novo {{c[2]}}</h2><p class="text-xs text-slate-500">Cadastro completo do módulo {{c[0]}}</p></div><button type="button" @click="modal=false"><X class="size-5"/></button></div><div class="grid grid-cols-2 gap-4 p-6"><div class="col-span-2"><label class="label">Nome / identificação *</label><input v-model="form.name" class="field"/></div><div><label class="label">Categoria / cargo / tipo *</label><input v-model="form.category" class="field"/></div><div><label class="label">Status</label><select v-model="form.status" class="field"><option v-for="value in moduleStatuses[kind]" :key="value">{{value}}</option></select></div><div><label class="label">Responsável / localização</label><input v-model="form.owner" class="field"/></div><div><label class="label">Informação principal</label><input v-model="form.info" class="field" placeholder="Datas, quantidade, custo ou resumo"/></div><div><label class="label">E-mail</label><input v-model="form.email" class="field" type="email"/></div><div><label class="label">Telefone</label><input v-model="form.phone" class="field"/></div><ModuleFields :kind="kind" :record="form"/><div class="col-span-2"><label class="label">Observações e detalhes</label><textarea v-model="form.notes" class="field h-24 py-2"/></div></div><div class="flex justify-end gap-2 border-t px-6 py-4 dark:border-slate-700"><button type="button" class="btn btn-secondary" @click="modal=false">Cancelar</button><button class="btn btn-primary">Salvar cadastro</button></div></form></div></template>
